![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

Add a validator check to enforce that the markdown readback tables are sorted lexicographically by their ID fields. This ensures that any manual edits or generator changes that break the ordering are caught during validation.

```javascript
    check(
      'source_provenance_preserved',
      rowsWithoutSourceRefs.length === 0 ? 'pass' : 'fail',
      'Every projection row preserves KG source_refs and a hash of the source surface rows; artifact receipts are preserved at top level.',
      { missing_question_keys: rowsWithoutSourceRefs.slice(0, 10).map((row) => row.question_key) },
    ),
    check(
      'readback_tables_sorted',
      (() => {
        const lines = readback.split('\n');
        const checkTableSorted = (header) => {
          const startIndex = lines.findIndex((line) => line.trim() === header);
          if (startIndex === -1) return true;
          const tableRows = [];
          for (let i = startIndex + 3; i < lines.length; i++) {
            const line = lines[i].trim();
            if (!line.startsWith('|')) break;
            const firstCell = line.split('|')[1].trim();
            tableRows.push(firstCell);
          }
          const sorted = [...tableRows].sort((left, right) => (left < right ? -1 : left > right ? 1 : 0));
          return JSON.stringify(tableRows) === JSON.stringify(sorted);
        };
        return checkTableSorted('## Representative Rows') && checkTableSorted('## Fixture Evaluations') ? 'pass' : 'fail';
      })(),
      'Markdown readback tables are sorted lexicographically by their ID fields to prevent diff churn.',
    ),
